#include <iostream>
#include <print>
#include <string>

class Account {
public:
    void deposit(long long n) {
        balance_ += n;
    }

    bool withdraw(long long n) {
        if (n > balance_) {
            return false;
        }
        balance_ -= n;
        return true;
    }

    long long balance() const {
        return balance_;
    }

private:
    long long balance_ = 0;
};

class SavingsAccount : public Account {
public:
    explicit SavingsAccount(int rate) : rate_(rate) {}

    bool withdraw(long long n) {
        if (withdrawals_ == 3 || !Account::withdraw(n)) {
            return false;
        }
        withdrawals_++;
        return true;
    }

    void end_month() {
        deposit(balance() * rate_ / 100);
        withdrawals_ = 0;
    }

private:
    int rate_;
    int withdrawals_ = 0;
};

int main() {
    int rate;
    std::cin >> rate;
    SavingsAccount account(rate);
    std::string command;
    while (std::cin >> command) {
        if (command == "dep") {
            long long n;
            std::cin >> n;
            account.deposit(n);
        } else if (command == "wd") {
            long long n;
            std::cin >> n;
            std::println("{}", account.withdraw(n) ? "ок" : "отказ");
        } else if (command == "month") {
            account.end_month();
        } else {
            std::println("{}", account.balance());
        }
    }
    return 0;
}

